 if r['status']=='ok' and not r.get('black') and not any(r.get('nsfw') or []):
  q=prompts[r['prompt_id']];main.append(dict(key=r['key'],image=str(O/r['normalized']),image_sha256=r['normalized_sha256'],prompt=q['prompt'],requirements=q['requirements']))
