protocol=dict(created_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),status='paired exploratory extension; original heldout outcomes already seen; not blind confirmation',model='Qwen/Qwen2.5-VL-7B-Instruct',model_revision='see immutable model-lock.json resolved before scoring',precision='bfloat16; no quantization fallback planned',runtime='Transformers 4.57.1 Qwen2_5_VLForConditionalGeneration; torch2.9.1 sdpa single CUDA device eval inference_mode',pixels=dict(min_pixels=256*28*28,max_pixels=512*28*28,source='original normalized 512x512 RGB; old stability bytes unchanged'),decode=dict(do_sample=False,num_beams=1,max_new_tokens=160,use_cache=True,seed=904),context_limit=2048,rubric=rubric,axes=axes,parse='json.loads entire stripped output; no markdown extraction or hand correction; exact keys, categorical values and integer bounds; no retries',vector='4 requirement values (no=0 partial=.5 yes=1; inapplicable=0) + 4 applicability masks + craft/10 + aesthetics/10; no sample metadata',quality='.6*mean(applicable requirements)+.25*craft/10+.15*aesthetics/10',stability='12 old images x3 deterministic votes first; repeatability only, not stochastic uncertainty; rubric fixed before scoring',main='215 usable original images once; complete cases shared for all comparisons; no retries; max251 successful planned calls, <=280 absolute',analysis=dict(classifier='original train StandardScaler and RidgeClassifier; alpha [100,10,1,.1], strict greater calibration accuracy selects first tie; no train+cal refit',splits='original frozen 12train/6calibration/6heldout prompt families',comparisons=['pickscore','visual','visual+pickscore','qwen','qwen+pickscore','qwen+visual+pickscore','qwen_quality'],bootstrap='2000 paired prompt-cluster resamples seed904; six heldout families; intervals descriptive with shared-seed dependence unresolved'),budgets=dict(setup_smoke_minutes=45,overall_minutes=120,hosted_usd=0),soft_logits='not retained: deterministic categorical outputs are primary; full vocabulary logits unnecessary memory/scope',prohibitions='no hosted inference, credentials, uploads, new images, original edits, product edits, commits, publishing',sources=['https://huggingface.co/Qwen/Qwen2.5-VL-7B-Instruct'],original_hashes={n:sha(O/n) for n in ['PROTOCOL.json','prompts.json','local-scores.npz','frozen-analysis.json','results.json']})
